// ======================================== // Apply Taxable Income Limitation // IRC § 246(b) // ========================================
result.drd_limitation_applies = true; result.drd_limitation_exception = false;
// Calculate limitation amounts // 50% DRD limited to 50% of taxable income before DRD result.drd_50pct_limitation_amount = result.drd_taxable_income_before_drd * result.drd_rate_50pct;
// 65% DRD limited to 65% of taxable income before DRD result.drd_65pct_limitation_amount = result.drd_taxable_income_before_drd * result.drd_rate_65pct;
// Apply limitations // 50% DRD: Lesser of tentative amount or limitation if (result.drd_domestic_50pct_tentative > 0) { result.drd_domestic_50pct_allowed = Math.min( result.drd_domestic_50pct_tentative, result.drd_50pct_limitation_amount ); } else { result.drd_domestic_50pct_allowed = 0.0; }
// 65% DRD: Lesser of tentative amount or limitation if (result.drd_domestic_65pct_tentative > 0) { result.drd_domestic_65pct_allowed = Math.min( result.drd_domestic_65pct_tentative, result.drd_65pct_limitation_amount ); } else { result.drd_domestic_65pct_allowed = 0.0; }
// Calculate total DRD // 100% DRD and § 245A not subject to limitation result.drd_total_allowed = result.drd_domestic_50pct_allowed + result.drd_domestic_65pct_allowed + result.drd_domestic_100pct_allowed + result.drd_section_245a_deduction;
// Add to audit trail if (result.audit_trail == null) { result.audit_trail = ""; }
String trail = "DRD TAXABLE INCOME LIMITATION (IRC § 246(b)):\n"; trail = trail + "Taxable income before DRD: $" + String.format("%.2f", result.drd_taxable_income_before_drd) + "\n\n";
if (result.drd_domestic_50pct_tentative > 0) { trail = trail + "50% DRD:\n"; trail = trail + " Tentative (50% × dividends): $" + String.format("%.2f", result.drd_domestic_50pct_tentative) + "\n"; trail = trail + " Limitation (50% × TI): $" + String.format("%.2f", result.drd_50pct_limitation_amount) + "\n"; trail = trail + " Allowed: $" + String.format("%.2f", result.drd_domestic_50pct_allowed) + "\n"; if (result.drd_domestic_50pct_allowed < result.drd_domestic_50pct_tentative) { trail = trail + " **LIMITED** (excess: $" + String.format("%.2f", result.drd_domestic_50pct_tentative - result.drd_domestic_50pct_allowed) + ")\n"; } trail = trail + "\n"; }
if (result.drd_domestic_65pct_tentative > 0) { trail = trail + "65% DRD:\n"; trail = trail + " Tentative (65% × dividends): $" + String.format("%.2f", result.drd_domestic_65pct_tentative) + "\n"; trail = trail + " Limitation (65% × TI): $" + String.format("%.2f", result.drd_65pct_limitation_amount) + "\n"; trail = trail + " Allowed: $" + String.format("%.2f", result.drd_domestic_65pct_allowed) + "\n"; if (result.drd_domestic_65pct_allowed < result.drd_domestic_65pct_tentative) { trail = trail + " **LIMITED** (excess: $" + String.format("%.2f", result.drd_domestic_65pct_tentative - result.drd_domestic_65pct_allowed) + ")\n"; } trail = trail + "\n"; }
if (result.drd_domestic_100pct_allowed > 0) { trail = trail + "100% DRD (Affiliated): $" + String.format("%.2f", result.drd_domestic_100pct_allowed) + " (NOT subject to limitation)\n\n"; }
if (result.drd_section_245a_deduction > 0) { trail = trail + "§ 245A Foreign DRD: $" + String.format("%.2f", result.drd_section_245a_deduction) + " (NOT subject to limitation)\n\n"; }
trail = trail + "TOTAL DRD ALLOWED: $" + String.format("%.2f", result.drd_total_allowed) + "\n\n";
